#version 300
uniform shader image;
uniform float2 size;
uniform float2 layer;
uniform float3x3 fromLayer;
uniform float3x3 toLayer;
uniform float4 screen;
uniform float time;
float2 amzCoord;
float4 amzOutput;
float2 amzScreenNorm() { float2 p=amzCoord-screen.xy; return float2(p.x/screen.z,1.0-p.y/screen.w); }
float2 amzLayerNorm() { float3 p=toLayer*float3(amzCoord,1.0); float2 n=p.xy/p.z/layer; return float2(n.x,1.0-n.y); }
float2 amzLayerCenter() { float3 p=fromLayer*float3(layer*.5,1.0); return p.xy/p.z-screen.xy; }
float4x4 amzRowMatrix(float3x3 m) { return float4x4(m[0].x,m[1].x,0.0,m[2].x, m[0].y,m[1].y,0.0,m[2].y, 0.0,0.0,1.0,0.0, m[0].z,m[1].z,0.0,m[2].z); }
float4x4 amzLayerToScreen() {
    float3x3 toNorm=float3x3(1.0/screen.z,0.0,0.0, 0.0,-1.0/screen.w,0.0,-screen.x/screen.z,1.0+screen.y/screen.w,1.0);
    float3x3 toPixels=float3x3(layer.x,0.0,0.0, 0.0,-layer.y,0.0, 0.0,layer.y,1.0);
    return amzRowMatrix(toNorm*fromLayer*toPixels);
}
float4x4 amzScreenToLayer() {
    float3x3 toPixels=float3x3(screen.z,0.0,0.0, 0.0,-screen.w,0.0, screen.x,screen.y+screen.w,1.0);
    float3x3 toNorm=float3x3(1.0/layer.x,0.0,0.0, 0.0,-1.0/layer.y,0.0,0.0,1.0,1.0);
    return amzRowMatrix(toNorm*toLayer*toPixels);
}
float2 getTexSize(float2 v) { return v; }
int amzIntMax(int a,int b) { return int(max(float(a),float(b))); }
int amzIntMin(int a,int b) { return int(min(float(a),float(b))); }
int amzIntAbs(int a) { return int(abs(float(a))); }
int amzIntClamp(int a,int b,int c) { return int(clamp(float(a),float(b),float(c))); }
uniform float2 amzVelocity,amzPivot,amzScale;
uniform float amzAngularVelocity,amzScaleVelocity,amzStartTime,amzEndTime;

struct AC_ImageInfo { int texture; float2 amzLocal_size; };
const float3x3 labPlaneInverse=float3x3(1);
float4x4 amzQuaternion(float4 q) {
    q /= max(length(q),0.000001);
    float x=q.x,y=q.y,z=q.z,w=q.w;
    return float4x4(1-2*(y*y+z*z),2*(x*y+w*z),2*(x*z-w*y),0,
                    2*(x*y-w*z),1-2*(x*x+z*z),2*(y*z+w*x),0,
                    2*(x*z+w*y),2*(y*z-w*x),1-2*(x*x+y*y),0,0,0,0,1);
}
const int amzPass=0;
uniform float amzIteration;
float4 amzSample_inputImg(float2 uv) { return float4(image.eval(((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/1.0))); }
float4 amzTexture(int tex,float2 uv) { if(tex==0) return amzSample_inputImg(uv);return float4(0.0); }
float4 amzTexture(int tex,float2 uv,float bias){return amzTexture(tex,uv);}
uniform float amzp_blurLength;
uniform float amzp_direction;
uniform float amzp_samples;
uniform float amzp_blurShape;
uniform float amzp_falloff;
uniform float amzp_sideMode;
uniform float amzp_angleSpread;
uniform float amzp_spread;
uniform float amzp_thin;
uniform float amzp_threshold;
uniform float amzp_displacePixels;
uniform float amzp_clampEdges;
uniform float amzp_centerX;
uniform float amzp_centerY;
uniform float amzp_radialFalloff;
uniform float amzp_mixAmount;
uniform float amzp_blendMode;
    float4 sampleTex(float2 uv){
      if((amzp_clampEdges>0.5)){
        uv = clamp(uv, 0.0, 1.0);
      }
      return amzTexture(0, uv);
    }
    float weightGaussian(float t, float fo){
      float sigma = 0.4 / max(fo, 0.01);
      return exp(-(t*t) / (2.0*sigma*sigma));
    }
    float weightLinear(float t, float fo){
      return max(0.0, 1.0 - abs(t) * fo);
    }
    float weightBox(float t){
      return 1.0;
    }
    float weightSinc(float t, float fo){
      if(abs(t) < 0.001) return 1.0;
      float x = t * fo * 3.14159265359 * 2.5;
      float sinc = sin(x) / x;
      float lx = t * fo * 3.14159265359;
      float window = (abs(lx) < 3.14159265359) ? (sin(lx)/lx) : 0.0;
      return clamp(sinc * window, 0.0, 1.0);
    }
    float getWeight(float t){
      if(int(amzp_blurShape)==0) return weightGaussian(t, amzp_falloff);
      if(int(amzp_blurShape)==1) return weightLinear(t, amzp_falloff);
      if(int(amzp_blurShape)==2) return weightBox(t);
      return weightSinc(t, amzp_falloff);
    }
    float4 blurSample(float2 uv, float2 blurVec, float halfLen,
                    float sampleCount, int side){
      float4 acc = float4(0.0);
      float wsum = 0.0;
      float N = sampleCount;
      float thinStep = 1.0 + amzp_thin * 3.0;
      for(float i = 0.0; i < 64.0; i += 1.0){
        if(i >= N) break;
        if(mod(i, max(thinStep, 1.0)) > 0.5 && i > 0.0) continue;
        float t = (N <= 1.0) ? 0.0 : i / (N - 1.0);
        float signedT;
        if(side == 0){
          signedT = t * 2.0 - 1.0;
        } else if(side == 1){
          signedT = t;
        } else {
          signedT = -t;
        }
        if(amzp_spread > 0.001){
          signedT = sign(signedT) * pow(abs(signedT), 1.0 - amzp_spread * 0.7);
        }
        float2 offset = blurVec * signedT * halfLen;
        float2 sampleUV;
        if((amzp_displacePixels>0.5)){
          sampleUV = uv + blurVec * halfLen + offset;
        } else {
          sampleUV = uv + offset;
        }
        float4 s = sampleTex(sampleUV);
        float w = getWeight(signedT);
        acc += s * w;
        wsum += w;
      }
      return (wsum > 0.0) ? acc / wsum : sampleTex(uv);
    }
    void amzRender(){
      float2 uv = amzScreenNorm();
      float4 orig = amzTexture(0, uv);
      float2 res = screen.zw;
      if(amzp_blurLength < 0.1){
        amzOutput = orig;
        return;
      }
      float dirRad = amzp_direction * 3.14159265359 / 180.0;
      float2 blurDir = float2(cos(dirRad), -sin(dirRad));
      float halfLen = (amzp_blurLength * 0.5) / res.x;
      float radMask = 1.0;
      if(amzp_radialFalloff > 0.001){
        float2 ctr = float2(amzp_centerX, amzp_centerY);
        float dist = length((uv - ctr) * float2(1.0, res.y/res.x));
        radMask = 1.0 - smoothstep(0.0, amzp_radialFalloff, dist);
        radMask = clamp(radMask, 0.0, 1.0);
      }
      float4 blurred = float4(0.0);
      float totalW = 0.0;
      int spreadSteps = (amzp_angleSpread > 0.5) ? 3 : 1;
      float spreadRad = amzp_angleSpread * 3.14159265359 / 180.0;
      for(int ai = 0; ai < 3; ai++){
        if(ai >= spreadSteps) break;
        float aOffset = 0.0;
        if(spreadSteps == 3){
          aOffset = (float(ai) - 1.0) * spreadRad * 0.5;
        }
        float ang = dirRad + aOffset;
        float2 bv = float2(cos(ang), -sin(ang));
        float angleW = (ai == 1) ? 0.5 : 1.0;
        blurred += blurSample(uv, bv, halfLen, amzp_samples, int(amzp_sideMode)) * angleW;
        totalW += angleW;
      }
      blurred /= max(totalW, 0.001);
      if(amzp_radialFalloff > 0.001){
        blurred = mix(orig, blurred, radMask);
      }
      if(amzp_threshold > 0.001){
        float origL = dot(orig.rgb, float3(0.299,0.587,0.114));
        float blurL = dot(blurred.rgb, float3(0.299,0.587,0.114));
        float diff = abs(origL - blurL);
        float tMask = smoothstep(0.0, amzp_threshold, diff);
        blurred = mix(orig, blurred, tMask);
      }
      float4 result = mix(orig, blurred, amzp_mixAmount);
      float3 origRGB = orig.rgb / max(orig.a, 0.001);
      float3 resultRGB = result.rgb / max(result.a, 0.001);
      if(int(amzp_blendMode) == 1){
        resultRGB = origRGB + resultRGB;
      } else if(int(amzp_blendMode) == 2){
        resultRGB = 1.0-(1.0-origRGB)*(1.0-resultRGB);
      } else if(int(amzp_blendMode) == 3){
        resultRGB = origRGB * resultRGB;
      }
      resultRGB = clamp(resultRGB, 0.0, 1.0);
      amzOutput = float4(resultRGB, orig.a) * orig.a;
    }

half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }

